)

router = APIRouter(prefix="/api/sustainability", tags=["sustainability"])


@router.get("/dashboard", response_model=SustainabilityDashboard)
def sustainability_dashboard(
    _: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> SustainabilityDashboard:
    return get_sustainability_dashboard(db)


@router.get("", response_model=SustainabilityListResponse)
def list_sustainability(
    _: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    q: str | None = None,
    reference_kind: str | None = None,
) -> SustainabilityListResponse:
    items, total, page, page_size = list_sustainability_service(
        db,
        page=page,
        page_size=page_size,
        q=q,
        reference_kind=reference_kind,
    )

    result = []
    for s in items:
        item = SustainabilityRead.model_validate(s)
        result.append(item)

    return SustainabilityListResponse(
        items=result,
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=SustainabilityRead, status_code=status.HTTP_201_CREATED)
def create_sustainability(
    body: SustainabilityCreate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> SustainabilityRead:
    from sqlalchemy.exc import IntegrityError

    try:
        sustainability = create_sustainability_service(db, body, current_user.id)
        return SustainabilityRead.model_validate(sustainability)
    except IntegrityError as e:
        db.rollback()
        raise HTTPException(status_code=409, detail="Sustainability record already exists") from e


